{
  "code": "export default async function ({ page }) {
  const EMAIL = 'jessicamendesbarbosa5@gmail.com';
  const SENHA = 'amovoced28';
  const w = (ms) => new Promise(r => setTimeout(r, ms));
  let debug = [];

  try {
    await page.setViewport({ width: 1280, height: 800 });

    // LOGIN
    await page.goto('https://app.cotadorsimplificado.com.br/login', { waitUntil: 'networkidle2', timeout: 30000 });
    debug.push('1-login page loaded');
    await w(1500);

    // EMAIL
    const eInp = await page.$('#email_principal');
    if (eInp) { 
      await eInp.click(); 
      await eInp.type(EMAIL, { delay: 30 }); 
      debug.push('2-email typed');
    } else {
      debug.push('2-EMAIL INPUT NOT FOUND');
    }
    await w(1000);

    // CONTINUAR COM EMAIL
    const contBtn = await page.evaluate(() => { 
      const b = [...document.querySelectorAll('button')].find(x => x.textContent.includes('Continuar com Email')); 
      if(b) { b.click(); return 'clicked'; }
      return 'not found';
    });
    debug.push('3-continuar: ' + contBtn);
    await w(2000);

    // SENHA - espera aparecer
    try {
      await page.waitForSelector('#pwdInput', { timeout: 10000 });
      debug.push('4-pwdInput appeared');
    } catch(e) {
      debug.push('4-pwdInput TIMEOUT - not found');
      // Verifica o que tem na página
      const pageContent = await page.evaluate(() => document.body ? document.body.innerText.substring(0, 200) : 'no body');
      debug.push('4b-page: ' + pageContent.substring(0, 100));
    }

    const sInp = await page.$('#pwdInput');
    if (sInp) { 
      await sInp.click(); 
      await sInp.type(SENHA, { delay: 30 }); 
      const senhaValue = await page.evaluate(() => document.querySelector('#pwdInput')?.value || 'empty');
      debug.push('5-senha typed, value length: ' + senhaValue.length);
    } else {
      debug.push('5-SENHA INPUT NOT FOUND');
    }
    await w(1000);

    // ENTRAR
    const entrarBtn = await page.evaluate(() => { 
      const buttons = document.querySelectorAll('button');
      const btnTexts = [...buttons].map(b => b.textContent.trim()).join(', ');
      const b = [...buttons].find(x => x.textContent.trim() === 'Entrar'); 
      if(b) { 
        b.click(); 
        return 'clicked';
      }
      return 'not found. buttons: ' + btnTexts.substring(0, 100);
    });
    debug.push('6-entrar: ' + entrarBtn);

    // ESPERA MAIS para login processar
    await w(6000);

    // URL APOS LOGIN
    const urlAfterLogin = page.url();
    debug.push('7-url after wait: ' + urlAfterLogin);

    // VERIFICA SE LOGOU - a pagina deveria mudar
    const pageAfterLogin = await page.evaluate(() => {
      if (!document.body) return 'no body';
      const text = document.body.innerText;
      const hasLogin = text.includes('Fazer login') || text.includes('Digite seu Email');
      const hasLoggedIn = text.includes('Hapvida') || text.includes('Cotador') || text.includes('Operadoras');
      return { hasLogin, hasLoggedIn, sample: text.substring(0, 150) };
    });
    debug.push('8-still login page: ' + pageAfterLogin.hasLogin);
    debug.push('9-logged in indicators: ' + pageAfterLogin.hasLoggedIn);
    debug.push('10-page sample: ' + (pageAfterLogin.sample || '').substring(0, 80));

    return { success: true, debug };
  } catch (error) {
    debug.push('ERROR: ' + error.message);
    return { success: false, error: error.message, debug };
  }
}"
}
